llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Gemcitabine, a deoxycytidine analog, has an oral bioavailability of only 10% in humans, showing that deoxycytidine nucleosides can undergo extensive first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Gemcitabine's low oral systemic exposure is attributed to first-pass metabolism by cytidine deaminase (CDA), a liability shared by decitabine as a deoxycytidine analog.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Zalcitabine (ddC), a dideoxycytidine analog, has high oral bioavailability (~88%), but its missing 2'/3' hydroxyls alter deaminase susceptibility and reduce transferability to decitabine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C39"],
      "claim": "DMDC, a cytidine analog with a 2'-methylidene sugar modification, has ~40% oral bioavailability, but the modified sugar makes it less transferable to unmodified 2'-deoxycytidine decitabine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Decitabine is a 5-aza-2'-deoxycytidine analog with no protective sugar modification; the closest relevant evidence, gemcitabine, shows only ~10% oral bioavailability due to cytidine deaminase first-pass metabolism. High-F cytidine analogs have modified sugars that reduce CDA susceptibility, so low F (<20%) is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for decitabine in the evidence set.",
    "No direct cytidine deaminase metabolism data for decitabine; reliance on gemcitabine as a surrogate.",
    "High-F cytidine analogs differ in sugar modifications that affect deaminase susceptibility, limiting transferability."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "not_applicable",
      "card_ids": [],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "none"
    }
  ],
  "revision_action": "initial"
}

